type OrderRepo interface { // دامنه قرارداد را تعریف می‌کند
    Save(o Order) error
}

type OrderService struct {
    repo OrderRepo // پیاده‌سازی از بیرون تزریق می‌شود
}

func (s *OrderService) Place(ctx context.Context, o Order) error {
    if o.Total <= 0 {
        return ErrInvalidTotal // خطای دامنه، نه خطای HTTP
    }
    return s.repo.Save(o)
}

type fakeRepo struct{ saved []Order }
func (f *fakeRepo) Save(o Order) error { f.saved = append(f.saved, o); return nil }

func TestPlace(t *testing.T) {
    f := &fakeRepo{}
    s := &OrderService{repo: f}
    err := s.Place(context.Background(), Order{Total: 100})
    if err != nil || len(f.saved) != 1 {
        t.Errorf("سفارش باید ذخیره می‌شد")
    }
}
